diff --git a/tests/notes-paging.test.mjs b/tests/notes-paging.test.mjs
new file mode 100644
index 0000000..90e9bd4
--- /dev/null
+++ b/tests/notes-paging.test.mjs
@@ -0,0 +1,94 @@
+import { test, before, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { createApp } from '../src/app/server.js';
+
+let server, base;
+before(async () => {
+  server = createApp().listen(0);
+  await new Promise((r) => server.once('listening', r));
+  base = `http://127.0.0.1:${server.address().port}`;
+});
+after(() => server.close());
+
+const post = (title, createdAt) => fetch(base + '/notes', {
+  method: 'POST', headers: { 'content-type': 'application/json', 'x-user': 'ayse' }, body: JSON.stringify({ title, createdAt }),
+}).then((r) => r.json());
+const get = (qs = '') => fetch(`${base}/notes${qs}`, { headers: { 'x-user': 'ayse' } });
+const ts = (n) => `2026-01-01T00:00:${String(n).padStart(2, '0')}.000Z`;
+
+// Pages through everything; returns the ids per page.
+async function walk(limit) {
+  const pages = [];
+  let cursor;
+  do {
+    const r = await get(`?limit=${limit}${cursor ? `&cursor=${encodeURIComponent(cursor)}` : ''}`);
+    assert.equal(r.status, 200);
+    pages.push((await r.json()).map((n) => n.id));
+    cursor = r.headers.get('x-next-cursor');
+  } while (cursor);
+  return pages;
+}
+
+test('Ö-P.1 empty store: empty array, no cursor', async () => {
+  const r = await get();
+  assert.equal(r.status, 200);
+  assert.deepEqual(await r.json(), []);
+  assert.equal(r.headers.get('x-next-cursor'), null);
+});
+
+test('Ö-P.2 default page is 20, newest first, body stays an array', async () => {
+  for (let i = 0; i < 25; i++) await post(`n${i}`, ts(i)); // inserted oldest first
+  const r = await get();
+  const notes = await r.json();
+  assert.ok(Array.isArray(notes));
+  assert.equal(notes.length, 20);
+  assert.deepEqual(notes.map((n) => n.createdAt), Array.from({ length: 20 }, (_, i) => ts(24 - i)));
+  assert.ok(r.headers.get('x-next-cursor'));
+});
+
+test('Ö-P.3 limit outside 1..100 or not an integer is 400', async () => {
+  for (const bad of ['0', '101', '-1', 'abc', '1.5', '', '1e1', ' 5', '0x10']) {
+    assert.equal((await get(`?limit=${encodeURIComponent(bad)}`)).status, 400, `limit=${bad}`);
+  }
+  assert.equal((await get('?limit=1')).status, 200);
+  assert.equal((await get('?limit=100')).status, 200);
+});
+
+test('Ö-P.4 walking the cursor returns every note once, newest first', async () => {
+  const all = (await (await get('?limit=100')).json()).map((n) => n.id);
+  assert.equal(all.length, 25);
+  const pages = await walk(7);
+  assert.deepEqual(pages.map((p) => p.length), [7, 7, 7, 4]);
+  assert.deepEqual(pages.flat(), all);
+});
+
+test('Ö-P.5 no cursor header when the last page is exactly full', async () => {
+  const r = await get('?limit=25');
+  assert.equal((await r.json()).length, 25);
+  assert.equal(r.headers.get('x-next-cursor'), null);
+});
+
+test('Ö-P.6 invalid cursor is 400', async () => {
+  const b64 = (v) => Buffer.from(v).toString('base64url');
+  for (const bad of ['garbage', b64('not json'), b64('{}'), b64('["x"]'), b64('[1,2]'), b64('["a","b","c"]'), '']) {
+    assert.equal((await get(`?cursor=${encodeURIComponent(bad)}`)).status, 400, `cursor=${bad}`);
+  }
+});
+
+test('Ö-P.7 notes with equal createdAt are neither skipped nor repeated', async () => {
+  for (let i = 0; i < 5; i++) await post(`tie${i}`, ts(59));
+  const all = (await (await get('?limit=100')).json()).map((n) => n.id);
+  assert.equal(all.length, 30);
+  assert.equal(new Set(all).size, 30);
+  assert.deepEqual((await walk(2)).flat(), all);
+});
+
+test('Ö-P.8 deleting the last note of a page does not break the next page', async () => {
+  const first = await get('?limit=3');
+  const page = await first.json();
+  const cursor = first.headers.get('x-next-cursor');
+  await fetch(`${base}/notes/${page[2].id}`, { method: 'DELETE' });
+  const rest = await (await get(`?limit=100&cursor=${encodeURIComponent(cursor)}`)).json();
+  assert.equal(rest.length, 27);
+  assert.ok(!rest.some((n) => page.some((p) => p.id === n.id)));
+});

