+
+// Paging. Fresh app per test so counts are exact.
+async function withApp(fn) {
+  const s = createApp().listen(0);
+  await new Promise((r) => s.once('listening', r));
+  const b = `http://127.0.0.1:${s.address().port}`;
+  const add = (title, createdAt) => fetch(b + '/notes', { method: 'POST', body: JSON.stringify({ title, createdAt }) });
+  try { await fn((path, init) => fetch(b + path, init), add); }
+  finally { s.close(); }
+}
+
+test('GET /notes is newest first, default limit 20, array body', async () => {
+  await withApp(async (get, add) => {
+    for (let i = 1; i <= 25; i++) await add(`n${i}`, new Date(2026, 0, i).toISOString());
+    const r = await get('/notes');
+    const page = await r.json();
+    assert.equal(page.length, 20);
+    assert.equal(page[0].title, 'n25');
+    assert.equal(page[19].title, 'n6');
+    assert.ok(r.headers.get('x-next-cursor'));
+  });
+});
+
+test('paging walks every note once, no header on last page', async () => {
+  await withApp(async (get, add) => {
+    for (let i = 1; i <= 7; i++) await add(`n${i}`, '2026-01-01T00:00:00.000Z'); // same createdAt: tie-break by id
+    const seen = [];
+    let cursor = null, pages = 0;
+    do {
+      const r = await get(`/notes?limit=3${cursor ? `&cursor=${encodeURIComponent(cursor)}` : ''}`);
+      seen.push(...(await r.json()).map((n) => n.title));
+      cursor = r.headers.get('x-next-cursor');
+      pages++;
+    } while (cursor);
+    assert.deepEqual(seen, ['n7', 'n6', 'n5', 'n4', 'n3', 'n2', 'n1']);
+    assert.equal(pages, 3);
+  });
+});
+
+test('exact multiple of limit: no next cursor on last full page', async () => {
+  await withApp(async (get, add) => {
+    for (let i = 1; i <= 4; i++) await add(`n${i}`, new Date(2026, 0, i).toISOString());
+    const r = await get('/notes?limit=4');
+    assert.equal((await r.json()).length, 4);
+    assert.equal(r.headers.get('x-next-cursor'), null);
+  });
+});
+
+test('cursor survives a delete of the last seen note', async () => {
+  await withApp(async (get, add) => {
+    for (let i = 1; i <= 5; i++) await add(`n${i}`, new Date(2026, 0, i).toISOString());
+    const r = await get('/notes?limit=2');
+    const [, last] = await r.json();
+    await get(`/notes/${last.id}`, { method: 'DELETE' });
+    const next = await (await get(`/notes?limit=2&cursor=${encodeURIComponent(r.headers.get('x-next-cursor'))}`)).json();
+    assert.deepEqual(next.map((n) => n.title), ['n3', 'n2']);
+  });
+});
+
+test('invalid limit is 400', async () => {
+  await withApp(async (get) => {
+    for (const l of ['0', '101', '-1', 'abc', '1.5', '']) assert.equal((await get(`/notes?limit=${l}`)).status, 400, l);
+    for (const l of ['1', '100']) assert.equal((await get(`/notes?limit=${l}`)).status, 200, l);
+  });
+});
+
+test('invalid cursor is 400', async () => {
+  await withApp(async (get) => {
+    const enc = (v) => Buffer.from(JSON.stringify(v)).toString('base64url');
+    for (const c of ['garbage', '', enc('x'), enc([1, 2]), enc(['2026', 'abc']), enc(['2026'])]) {
+      assert.equal((await get(`/notes?cursor=${c}`)).status, 400, c);
+    }
+  });
+});

