+before(async () => {
+  server = createApp().listen(0);
+  await new Promise((r) => server.once('listening', r));
+  base = `http://127.0.0.1:${server.address().port}`;
+  // 45 notes; pairs share a timestamp to exercise the tie-break.
+  for (let i = 0; i < 45; i++) await post(`n${i}`, new Date(Date.UTC(2026, 0, 1, 0, Math.floor(i / 2))).toISOString());
+});
+after(() => server.close());
+
+const post = (title, createdAt) => fetch(base + '/notes', {
+  method: 'POST', headers: { 'content-type': 'application/json', 'x-user': 'ayse' }, body: JSON.stringify({ title, createdAt }),
+}).then((r) => r.json());
+const get = (qs = '') => fetch(`${base}/notes${qs}`, { headers: { 'x-user': 'ayse' } });
+
+
+async function walk(limit) {
+  const seen = [];
+  let cursor;
+  for (let guard = 0; guard < 100; guard++) {
+    const r = await get(`?limit=${limit}${cursor ? `&cursor=${encodeURIComponent(cursor)}` : ''}`);
+    assert.equal(r.status, 200);
+    seen.push(...(await r.json()));
+    cursor = r.headers.get('x-next-cursor');
+    if (!cursor) return seen;
+  }
+  assert.fail('cursor never ended');
+}
